    "corrected_product_id" bigint,
    "correction_type" varchar(50),
    "quantity_before" integer NOT NULL DEFAULT 0,
    "quantity_after" integer NOT NULL DEFAULT 0,
    "serial_number_before" varchar(100),
    "serial_number_after" varchar(100),
    "receiving_detail_id" bigint,
    "serial_id" bigint,
    "reason" text,
    "corrected_by" bigint,
    "approved_by" bigint,
    "created_at" timestamp(0) without time zone,
    "updated_at" timestamp(0) without time zone,
    CONSTRAINT "scan_corrections_pkey" PRIMARY KEY ("correction_id")
);
COMMENT ON COLUMN "scan_corrections"."original_barcode" IS 'The barcode that was scanned incorrectly';
COMMENT ON COLUMN "scan_corrections"."original_product_id" IS 'Product the barcode was originally matched to';
COMMENT ON COLUMN "scan_corrections"."corrected_barcode" IS 'The correct barcode (if barcode changed)';
COMMENT ON COLUMN "scan_corrections"."corrected_product_id" IS 'Product the barcode should have been matched to';
COMMENT ON COLUMN "scan_corrections"."reason" IS 'Why this correction was made';

--
-- Table: sessions
--
