    "deleted_at" timestamp(0) without time zone,
    "created_at" timestamp(0) without time zone,
    "updated_at" timestamp(0) without time zone,
    CONSTRAINT "warranty_claims_pkey" PRIMARY KEY ("claim_id"),
    CONSTRAINT "warranty_claims_claim_type_check" CHECK ("claim_type" IN ('repair', 'replacement'))
);

--
-- Table: warranty_claim_details
--
CREATE TABLE "warranty_claim_details" (
    "claim_detail_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
