    "serial_number" varchar(100),
    "quantity_requested" integer NOT NULL DEFAULT 0,
    "quantity_issued" integer NOT NULL DEFAULT 1,
    "quantity_in_pieces" integer NOT NULL DEFAULT 1,
    "quantity_unit" varchar(50),
    "unit_cost" numeric(12,2) NOT NULL DEFAULT 0.00,
    "line_cost" numeric(12,2) NOT NULL DEFAULT 0.00,
    "created_at" timestamp(0) without time zone,
    "updated_at" timestamp(0) without time zone,
    CONSTRAINT "warranty_claim_details_pkey" PRIMARY KEY ("claim_detail_id")
);

