    "product_id" bigint NOT NULL,
    "serial_number" varchar(100) NOT NULL,
    "location_id" bigint NOT NULL,
    "holding_status" varchar(30) NOT NULL DEFAULT 'warranty_holding',
    "received_at" timestamp(0) without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "released_at" timestamp(0) without time zone,
    "release_disposition" varchar(30),
    "replacement_warranty_id" bigint,
    "created_at" timestamp(0) without time zone,
    "updated_at" timestamp(0) without time zone,
    CONSTRAINT "warranty_claim_returns_pkey" PRIMARY KEY ("return_id")
);

