);

--
-- Table: warranty_records
--
CREATE TABLE "warranty_records" (
    "warranty_id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "issuance_id" bigint,
    "issuance_detail_id" bigint,
    "product_id" bigint,
    "serial_number" varchar(100),
    "customer_id" bigint,
    "sale_date" date,
    "warranty_start_date" date,
    "warranty_end_date" date,
    "warranty_period_months" integer NOT NULL DEFAULT 0,
    "warranty_duration_label" varchar(30),
    "status_id" bigint,
    "notes" text,
    "claim_date" date,
    "claimed_by" bigint,
    "claim_notes" text,
    "created_at" timestamp(0) without time zone,
    "updated_at" timestamp(0) without time zone,
    CONSTRAINT "warranty_records_pkey" PRIMARY KEY ("warranty_id")
);
COMMENT ON COLUMN "warranty_records"."warranty_duration_label" IS 'e.g. 2 Years, 6 Months, No Warranty';

